  uint8_t filter_codes[BLOSC2_MAX_FILTERS];
  int16_t reserved1;
  uint8_t filter_meta[BLOSC2_MAX_FILTERS];
  uint8_t reserved2;
  uint8_t blosc2_flags;
} blosc_header;


